import inspect
import hamana

# List available classes and functions
print("hamana module contents:")
for name in dir(hamana):
    if not name.startswith('_'):
        obj = getattr(hamana, name)
        print(f"  {name}: {type(obj).__name__}")

# Check for database/connection classes
if hasattr(hamana, 'Database'):
    print("\nDatabase class methods:")
    for name, method in inspect.getmembers(hamana.Database, predicate=inspect.ismethod):
        if not name.startswith('_'):
            print(f"  {name}")

# List exceptions
print("\nAvailable exceptions:")
for name in dir(hamana):
    obj = getattr(hamana, name)
    if isinstance(obj, type) and issubclass(obj, Exception):
        print(f"  {name}")
